// SPDX-License-Identifier: MIT
//! Script-tree builder tests. Anchor: every `scriptPubKey` row of BIP341's
//! `wallet-test-vectors.json` that has a `scriptTree` (`tree_vectors.zig`,
//! generated by `tools/gen_tree_vectors.py`): leaf hashes, Merkle root, tweak,
//! output key, scriptPubKey and EVERY control block, byte-exact — from both
//! the explicit-shape and the depth-list entry point.

const std = @import("std");
const bip340 = @import("bip340");
const taproot = @import("root.zig");
const tree = @import("tree.zig");
const v = @import("tree_vectors.zig");

const testing = std.testing;
const ta = testing.allocator;

fn hexAlloc(hex: []const u8) ![]u8 {
    const out = try ta.alloc(u8, hex.len / 2);
    errdefer ta.free(out);
    _ = try std.fmt.hexToBytes(out, hex);
    return out;
}

fn hex32(hex: []const u8) ![32]u8 {
    var out: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&out, hex);
    return out;
}

/// Assert every published value of `row` against `info`; returns how many
/// control blocks were compared.
fn checkRow(row: v.Row, info: tree.SpendInfo) !usize {
    try testing.expectEqualSlices(u8, &try hex32(row.merkle_root), &info.merkle_root.?);
    try testing.expectEqualSlices(u8, &try hex32(row.tweak), &info.tweak);
    try testing.expectEqualSlices(u8, &try hex32(row.tweaked_pubkey), &info.output.x);
    const spk = try hexAlloc(row.script_pub_key);
    defer ta.free(spk);
    try testing.expectEqual(@as(usize, 34), spk.len);
    try testing.expectEqualSlices(u8, &[_]u8{ 0x51, 0x20 }, spk[0..2]);
    try testing.expectEqualSlices(u8, spk[2..], &info.output.x);

    try testing.expectEqual(row.leaf_hashes.len, info.leaves.len);
    try testing.expectEqual(row.control_blocks.len, info.leaves.len);
    for (info.leaves, 0..) |leaf, i| {
        try testing.expectEqualSlices(u8, &try hex32(row.leaf_hashes[i]), &leaf.leaf_hash);
        const want = try hexAlloc(row.control_blocks[i]);
        defer ta.free(want);
        try testing.expectEqual(want.len, info.controlBlockLen(i));
        try testing.expectEqual(@as(usize, 33) + 32 * leaf.path.len, want.len);
        const got = try info.controlBlockAlloc(ta, i);
        defer ta.free(got);
        try testing.expectEqualSlices(u8, want, got);
    }
    return info.leaves.len;
}

test "BIP341 vectors: explicit shape reproduces every published value and control block" {
    var checked: usize = 0;
    for (v.rows) |row| {
        const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(row.internal_pubkey));
        var info = try tree.buildFromTree(ta, internal, &row.tree);
        defer info.deinit(ta);
        checked += try checkRow(row, info);
    }
    try testing.expectEqual(@as(usize, v.control_block_count), checked);
    try testing.expectEqual(@as(usize, 12), checked);
}

test "BIP341 vectors: depth-list form gives the same results as the explicit form" {
    for (v.rows) |row| {
        const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(row.internal_pubkey));
        var a = try tree.buildFromTree(ta, internal, &row.tree);
        defer a.deinit(ta);
        var b = try tree.buildFromLeaves(ta, internal, row.leaves);
        defer b.deinit(ta);
        _ = try checkRow(row, b);
        try testing.expectEqual(a.leaves.len, b.leaves.len);
        for (a.leaves, b.leaves) |x, y| {
            try testing.expectEqualSlices(u8, &x.leaf_hash, &y.leaf_hash);
            try testing.expectEqualSlices([32]u8, x.path, y.path);
        }
    }
}

test "single leaf: root is the leaf hash, empty path, 33-byte control block" {
    const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    const script = [_]u8{0x51};
    var info = try tree.buildFromLeaves(ta, internal, &.{.{ .depth = 0, .script = &script }});
    defer info.deinit(ta);
    try testing.expectEqualSlices(u8, &tree.tapLeafHash(0xc0, &script), &info.merkle_root.?);
    try testing.expectEqual(@as(usize, 0), info.leaves[0].path.len);
    var buf: [33]u8 = undefined;
    const cb = info.controlBlock(0, &buf);
    try testing.expectEqual(@as(usize, 33), cb.len);
    try testing.expectEqual(@as(u8, 0xc0 | @as(u8, info.output.parity)), cb[0]);
    try testing.expectEqualSlices(u8, &internal.toBytes(), cb[1..]);
}

test "empty tree is key-path-only: null root, same output as tweakPublicKey(null)" {
    const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    var info = try tree.buildFromLeaves(ta, internal, &.{});
    defer info.deinit(ta);
    try testing.expect(info.merkle_root == null);
    try testing.expectEqual(@as(usize, 0), info.leaves.len);
    const want = try taproot.tweakPublicKey(internal, null);
    try testing.expectEqualSlices(u8, &want.output.x, &info.output.x);
    var info2 = try tree.buildFromTree(ta, internal, null);
    defer info2.deinit(ta);
    try testing.expectEqualSlices(u8, &want.output.x, &info2.output.x);
}

test "tapBranchHash is symmetric; tapLeafHash commits to version and script" {
    const a = try hex32(v.rows[3].leaf_hashes[0]);
    const b = try hex32(v.rows[3].leaf_hashes[1]);
    try testing.expectEqualSlices(u8, &tree.tapBranchHash(a, b), &tree.tapBranchHash(b, a));
    try testing.expect(!std.mem.eql(u8, &tree.tapLeafHash(0xc0, "x"), &tree.tapLeafHash(0xc2, "x")));
    try testing.expect(!std.mem.eql(u8, &tree.tapLeafHash(0xc0, "x"), &tree.tapLeafHash(0xc0, "y")));
}

test "leaf script longer than 252 bytes uses a multi-byte CompactSize" {
    // 300-byte script: prefix fd 2c 01. Compare against a manual tagged hash.
    var script: [300]u8 = undefined;
    @memset(&script, 0xab);
    var h = bip340.hash.taggedHasher("TapLeaf");
    h.update(&[_]u8{ 0xc0, 0xfd, 0x2c, 0x01 });
    h.update(&script);
    try testing.expectEqualSlices(u8, &h.finalResult(), &tree.tapLeafHash(0xc0, &script));
}

// ── Huffman layout (`huffmanLeaves` / `buildFromWeights`) ─────────────────
//
// Reference: rust-bitcoin `TaprootBuilder::with_huffman_tree` (two lowest
// weights joined, u32 saturating sum, ties by larger node hash, EmptyTree on
// no input). The expected roots/orders below were computed by an independent
// sort-based re-implementation of that algorithm (hashlib only, no heap);
// rust-bitcoin's own `build_huffman_tree` test publishes only the depths
// (51:3 52:2 53:2 54:2 55:3), which the first test also pins. Weights are
// those of that test; the scripts' semantics do not matter.

fn wl(weight: u32, byte: u8) tree.WeightedLeaf {
    const S = struct {
        const bytes = blk: {
            var b: [256][1]u8 = undefined;
            for (&b, 0..) |*x, i| x.* = .{@intCast(i)};
            break :blk b;
        };
    };
    return .{ .weight = weight, .script = &S.bytes[byte] };
}

/// Fold a leaf hash up its path to the Merkle root.
fn rootFromPath(leaf_hash: [32]u8, path: []const [32]u8) [32]u8 {
    var h = leaf_hash;
    for (path) |p| h = tree.tapBranchHash(h, p);
    return h;
}

fn expectHuffman(items: []const tree.WeightedLeaf, root_hex: []const u8, order: []const struct { u8, u8 }) !void {
    const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    const list = try tree.huffmanLeaves(ta, items);
    defer ta.free(list);
    try testing.expectEqual(order.len, list.len);
    for (list, order) |l, o| {
        try testing.expectEqual(o[0], l.depth);
        try testing.expectEqual(o[1], l.script[0]);
    }
    var info = try tree.buildFromWeights(ta, internal, items);
    defer info.deinit(ta);
    try testing.expectEqualSlices(u8, &try hex32(root_hex), &info.merkle_root.?);
    for (info.leaves) |leaf| {
        try testing.expectEqualSlices(u8, &info.merkle_root.?, &rootFromPath(leaf.leaf_hash, leaf.path));
    }
}

test "huffman: rust-bitcoin build_huffman_tree weights (depths) and root" {
    try expectHuffman(
        &.{ wl(10, 0x51), wl(20, 0x52), wl(20, 0x53), wl(30, 0x54), wl(19, 0x55) },
        "ff1d976bc9fdc9340e74a03ba0a04b263adcd30a111da1fd57a83e0f7588274b",
        &.{ .{ 3, 0x55 }, .{ 3, 0x51 }, .{ 2, 0x54 }, .{ 2, 0x53 }, .{ 2, 0x52 } },
    );
}

test "huffman: equal weights are broken by node hash (larger hash joins first)" {
    try expectHuffman(
        &.{ wl(1, 0x51), wl(1, 0x52), wl(1, 0x53) },
        "609f09890e4348cc5bcc26e51c432c7830162715d64aab7c306f853c9da06a7b",
        &.{ .{ 2, 0x51 }, .{ 2, 0x52 }, .{ 1, 0x53 } },
    );
    try expectHuffman(
        &.{ wl(5, 0x51), wl(5, 0x52), wl(5, 0x53), wl(5, 0x54), wl(5, 0x55), wl(5, 0x56), wl(5, 0x57) },
        "398caf1fc88ca2cbd7017cc107c5ffeec24b95e25ba8747a5227bafd0958f38d",
        &.{ .{ 3, 0x52 }, .{ 3, 0x56 }, .{ 3, 0x53 }, .{ 3, 0x51 }, .{ 2, 0x55 }, .{ 3, 0x57 }, .{ 3, 0x54 } },
    );
}

test "huffman: weight sums saturate at u32 max instead of wrapping" {
    // 1+1 = 2 joins first; 2 + max = saturated max, which then ties with the
    // other max leaf. A wrapping sum (2^32+1 -> 1) would put that node first
    // and give a different shape.
    try expectHuffman(
        &.{ wl(std.math.maxInt(u32), 0x51), wl(std.math.maxInt(u32), 0x52), wl(1, 0x53), wl(1, 0x54) },
        "0af1dec028ec6503db9a2c0d93829ec399d2b5aa3bda59f9302d24d41ed8a7f7",
        &.{ .{ 3, 0x54 }, .{ 3, 0x53 }, .{ 2, 0x52 }, .{ 1, 0x51 } },
    );
}

test "huffman: single leaf is a depth-0 tree; empty and bad version are errors" {
    try expectHuffman(&.{wl(7, 0x51)}, "a85b2107f791b26a84e7586c28cec7cb61202ed3d01944d832500f363782d675", &.{.{ 0, 0x51 }});
    try testing.expectError(error.EmptyTree, tree.huffmanLeaves(ta, &.{}));
    const k = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    try testing.expectError(error.EmptyTree, tree.buildFromWeights(ta, k, &.{}));
    var bad = wl(1, 0x51);
    bad.version = 0xc1;
    try testing.expectError(error.InvalidLeafVersion, tree.huffmanLeaves(ta, &.{ wl(1, 0x52), bad }));
    bad.version = 0x50;
    try testing.expectError(error.InvalidLeafVersion, tree.huffmanLeaves(ta, &.{bad}));
}

test "huffman: per-leaf versions are hashed and carried into the depth list" {
    var a = wl(10, 0x51);
    a.version = 0xc2;
    var c = wl(5, 0x53);
    c.version = 0xc4;
    const items = [_]tree.WeightedLeaf{ a, wl(20, 0x52), c };
    const list = try tree.huffmanLeaves(ta, &items);
    defer ta.free(list);
    try testing.expectEqual(@as(usize, 3), list.len);
    const want = [_]struct { u8, u8, u8 }{ .{ 2, 0x51, 0xc2 }, .{ 2, 0x53, 0xc4 }, .{ 1, 0x52, 0xc0 } };
    for (list, want) |l, w| {
        try testing.expectEqual(w[0], l.depth);
        try testing.expectEqual(w[1], l.script[0]);
        try testing.expectEqual(w[2], l.version);
    }
    const k = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    var info = try tree.buildFromWeights(ta, k, &items);
    defer info.deinit(ta);
    try testing.expectEqualSlices(u8, &try hex32("835e7467367afd2f1f460ea79ad03bccc184bc701534986b0f6e546a3f28adda"), &info.merkle_root.?);
}

/// Straight-line reference of the same rule, with no heap: repeatedly scan for
/// the lowest weight (larger hash first on a tie), join, count depths.
fn referenceHuffman(items: []const tree.WeightedLeaf, depths: []usize) [32]u8 {
    const Node = struct { w: u32, h: [32]u8, first: usize };
    var nodes: [80]Node = undefined;
    var links: [80]?usize = undefined; // members of a node form a linked chain by leaf index
    var live: [80]bool = undefined;
    var count = items.len;
    for (items, 0..) |l, i| {
        nodes[i] = .{ .w = l.weight, .h = tree.tapLeafHash(l.version, l.script), .first = i };
        links[i] = null;
        live[i] = true;
        depths[i] = 0;
    }
    var remaining = items.len;
    while (remaining > 1) {
        var picks: [2]usize = undefined;
        for (&picks, 0..) |*pk, round| {
            var best: ?usize = null;
            for (0..count) |i| {
                if (!live[i]) continue;
                if (round == 1 and i == picks[0]) continue;
                const b = best orelse {
                    best = i;
                    continue;
                };
                const better = nodes[i].w < nodes[b].w or
                    (nodes[i].w == nodes[b].w and std.mem.order(u8, &nodes[i].h, &nodes[b].h) == .gt);
                if (better) best = i;
            }
            pk.* = best.?;
        }
        const a = picks[0];
        const b = picks[1];
        // every member of a and b gets one level deeper; chain b after a
        var m: ?usize = nodes[a].first;
        var last: usize = nodes[a].first;
        while (m) |x| : (m = links[x]) {
            depths[x] += 1;
            last = x;
        }
        links[last] = nodes[b].first;
        m = nodes[b].first;
        while (m) |x| : (m = links[x]) depths[x] += 1;
        nodes[count] = .{
            .w = @intCast(@min(@as(u64, nodes[a].w) + nodes[b].w, std.math.maxInt(u32))),
            .h = tree.tapBranchHash(nodes[a].h, nodes[b].h),
            .first = nodes[a].first,
        };
        live[a] = false;
        live[b] = false;
        live[count] = true;
        count += 1;
        remaining -= 1;
    }
    for (0..count) |i| if (live[i]) return nodes[i].h;
    unreachable;
}

test "huffman: matches a straight-line reference on random weights (ties, zeros, saturation)" {
    var prng = std.Random.DefaultPrng.init(0x7a9c_0de5);
    const rnd = prng.random();
    const k = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    const special = [_]u32{ 0, 1, 2, 3, 5, 1 << 31, std.math.maxInt(u32) - 1, std.math.maxInt(u32) };
    for (0..200) |_| {
        const n = 1 + rnd.uintLessThan(usize, 40);
        var scripts: [40][2]u8 = undefined;
        var items: [40]tree.WeightedLeaf = undefined;
        const small = rnd.boolean();
        for (0..n) |i| {
            scripts[i] = .{ @intCast(i), rnd.int(u8) };
            const w: u32 = if (small) rnd.uintLessThan(u32, 4) else special[rnd.uintLessThan(usize, special.len)];
            items[i] = .{ .weight = w, .script = &scripts[i] };
        }
        var depths: [40]usize = undefined;
        const want_root = referenceHuffman(items[0..n], &depths);
        const list = try tree.huffmanLeaves(ta, items[0..n]);
        defer ta.free(list);
        try testing.expectEqual(n, list.len);
        for (list) |l| try testing.expectEqual(depths[l.script[0]], @as(usize, l.depth));
        var info = try tree.buildFromWeights(ta, k, items[0..n]);
        defer info.deinit(ta);
        try testing.expectEqualSlices(u8, &want_root, &info.merkle_root.?);
    }
}

test "huffman: depth 128 is accepted, 129 is TreeTooDeep (reachable through hash ties at saturated weights)" {
    // All weights u32 max (every sum saturates), every leaf hash starting with
    // 0x00 (ground by scanning a counter) while the growing subtree's hash
    // almost never does: each round then joins the subtree with the
    // largest-hash remaining leaf, a chain of depth n - 1.
    var scripts: [130][2]u8 = undefined;
    var items: [130]tree.WeightedLeaf = undefined;
    var found: usize = 0;
    var c: u32 = 0;
    while (found < 130) : (c += 1) {
        const s = [2]u8{ @intCast(c >> 8), @intCast(c & 0xff) };
        if (tree.tapLeafHash(tree.default_leaf_version, &s)[0] != 0) continue;
        scripts[found] = s;
        items[found] = .{ .weight = std.math.maxInt(u32), .script = &scripts[found] };
        found += 1;
    }
    const ok = try tree.huffmanLeaves(ta, items[0..129]);
    defer ta.free(ok);
    var max_depth: u8 = 0;
    for (ok) |l| max_depth = @max(max_depth, l.depth);
    try testing.expectEqual(@as(u8, 128), max_depth);
    try testing.expectError(error.TreeTooDeep, tree.huffmanLeaves(ta, items[0..130]));
    const k = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    try testing.expectError(error.TreeTooDeep, tree.buildFromWeights(ta, k, items[0..130]));
}

test "huffman: the Merkle root does not depend on input order; weights matter" {
    const k = try bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
    const a = [_]tree.WeightedLeaf{ wl(10, 0x51), wl(20, 0x52), wl(20, 0x53), wl(30, 0x54), wl(19, 0x55) };
    const b = [_]tree.WeightedLeaf{ wl(19, 0x55), wl(30, 0x54), wl(10, 0x51), wl(20, 0x53), wl(20, 0x52) };
    var ia = try tree.buildFromWeights(ta, k, &a);
    defer ia.deinit(ta);
    var ib = try tree.buildFromWeights(ta, k, &b);
    defer ib.deinit(ta);
    try testing.expectEqualSlices(u8, &ia.merkle_root.?, &ib.merkle_root.?);
    try testing.expectEqualSlices(u8, &ia.output.x, &ib.output.x);
    // Different weights give a different shape, hence a different root.
    const c = [_]tree.WeightedLeaf{ wl(100, 0x51), wl(20, 0x52), wl(20, 0x53), wl(30, 0x54), wl(19, 0x55) };
    var ic = try tree.buildFromWeights(ta, k, &c);
    defer ic.deinit(ta);
    try testing.expect(!std.mem.eql(u8, &ia.merkle_root.?, &ic.merkle_root.?));
}

// Mutation run 2026-10-05: moving either CompactSize boundary by one left
// the suite green (the test above sits at 300, far from both). Bitcoin's
// CompactSize: n < 0xfd is one byte; 0xfd..0xffff is fd + u16 LE; above that
// fe + u32 LE. 252/253 and 65535/65536 are the two edges a script can reach.
test "leaf CompactSize edges: 252, 253, 65535, 65536 bytes" {
    const Case = struct { len: usize, prefix: []const u8 };
    const cases = [_]Case{
        .{ .len = 252, .prefix = &.{0xfc} },
        .{ .len = 253, .prefix = &.{ 0xfd, 0xfd, 0x00 } },
        .{ .len = 65535, .prefix = &.{ 0xfd, 0xff, 0xff } },
        .{ .len = 65536, .prefix = &.{ 0xfe, 0x00, 0x00, 0x01, 0x00 } },
    };
    const script = try ta.alloc(u8, 65536);
    defer ta.free(script);
    @memset(script, 0xab);
    for (cases) |c| {
        var h = bip340.hash.taggedHasher("TapLeaf");
        h.update(&[_]u8{0xc0});
        h.update(c.prefix);
        h.update(script[0..c.len]);
        try testing.expectEqualSlices(u8, &h.finalResult(), &tree.tapLeafHash(0xc0, script[0..c.len]));
    }
}

fn internalKey() !bip340.XOnlyPublicKey {
    return bip340.XOnlyPublicKey.fromBytes(try hex32(v.rows[0].internal_pubkey));
}

test "invalid depth lists are typed errors" {
    const k = try internalKey();
    const s = "\x51";
    const L = tree.DepthLeaf;
    // Incomplete: a lone depth-1 leaf, a missing sibling.
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{L{ .depth = 1, .script = s }}));
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = s }, L{ .depth = 2, .script = s } }));
    // Overfull: a depth-0 leaf is the whole tree.
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 0, .script = s }, L{ .depth = 0, .script = s } }));
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = s }, L{ .depth = 1, .script = s }, L{ .depth = 1, .script = s } }));
    // Wrong depth-first order (2,1,2 never completes).
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 2, .script = s }, L{ .depth = 1, .script = s }, L{ .depth = 2, .script = s } }));
    // Valid: 1,2,2 and 2,2,1.
    var ok = try tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = s }, L{ .depth = 2, .script = "\x52" }, L{ .depth = 2, .script = "\x53" } });
    ok.deinit(ta);
    var ok2 = try tree.buildFromLeaves(ta, k, &.{ L{ .depth = 2, .script = s }, L{ .depth = 2, .script = "\x52" }, L{ .depth = 1, .script = "\x53" } });
    ok2.deinit(ta);
}

test "invalid leaf versions are typed errors" {
    const k = try internalKey();
    for ([_]u8{ 0xc1, 0x01, 0xff, 0x50 }) |ver| {
        try testing.expectError(error.InvalidLeafVersion, tree.buildFromLeaves(ta, k, &.{.{ .depth = 0, .version = ver, .script = "\x51" }}));
        const n: tree.Node = .{ .leaf = .{ .version = ver, .script = "\x51" } };
        try testing.expectError(error.InvalidLeafVersion, tree.buildFromTree(ta, k, &n));
    }
    // Even versions other than 0xc0 (incl. 0x00 and 0xfa from the vectors) are fine.
    for ([_]u8{ 0x00, 0x52, 0xfa, 0xfe }) |ver| {
        var info = try tree.buildFromLeaves(ta, k, &.{.{ .depth = 0, .version = ver, .script = "\x51" }});
        defer info.deinit(ta);
        try testing.expectEqual(ver, info.leaves[0].version);
    }
}

test "depth limit: 128 accepted, 129 rejected (list and explicit)" {
    const k = try internalKey();
    const s = "\x51";
    // A degenerate ("comb") tree of depth d: leaves at depths 1,2,...,d,d.
    const build = struct {
        fn run(d: u8, alloc: std.mem.Allocator) !?tree.SpendInfo {
            var list = try alloc.alloc(tree.DepthLeaf, d + 1);
            defer alloc.free(list);
            for (0..d) |i| list[i] = .{ .depth = @intCast(i + 1), .script = "\x51" };
            list[d] = .{ .depth = d, .script = "\x52" };
            return try tree.buildFromLeaves(alloc, kk(), list);
        }
        fn kk() bip340.XOnlyPublicKey {
            return bip340.XOnlyPublicKey.fromBytes(hex32(v.rows[0].internal_pubkey) catch unreachable) catch unreachable;
        }
    };
    _ = s;
    var ok = (try build.run(128, ta)).?;
    defer ok.deinit(ta);
    try testing.expectEqual(@as(usize, 128), ok.leaves[127].path.len);
    try testing.expectEqual(@as(usize, 33 + 32 * 128), ok.controlBlockLen(127));
    try testing.expectError(error.TreeTooDeep, build.run(129, ta));
    try testing.expectError(error.TreeTooDeep, tree.buildFromLeaves(ta, k, &.{.{ .depth = 255, .script = "\x51" }}));

    // Explicit: a right-leaning chain of 129 branches is too deep, 128 fine.
    var nodes: [131]tree.Node = undefined;
    const leaf: tree.Node = .{ .leaf = .{ .script = "\x51" } };
    nodes[0] = leaf;
    for (1..131) |i| nodes[i] = .{ .branch = .{ &leaf, &nodes[i - 1] } };
    var deep_ok = try tree.buildFromTree(ta, k, &nodes[128]);
    deep_ok.deinit(ta);
    try testing.expectError(error.TreeTooDeep, tree.buildFromTree(ta, k, &nodes[129]));
}

test "no leaks on the error paths (testing.allocator checks)" {
    const k = try internalKey();
    const L = tree.DepthLeaf;
    try testing.expectError(error.InvalidTreeShape, tree.buildFromLeaves(ta, k, &.{ L{ .depth = 1, .script = "\x51" }, L{ .depth = 1, .script = "\x51" }, L{ .depth = 0, .script = "\x51" } }));
    // Allocation failure at every point.
    const list = [_]L{ .{ .depth = 1, .script = "\x51" }, .{ .depth = 2, .script = "\x52" }, .{ .depth = 2, .script = "\x53" } };
    var fail: usize = 0;
    while (fail < 40) : (fail += 1) {
        var fa = testing.FailingAllocator.init(ta, .{ .fail_index = fail });
        if (tree.buildFromLeaves(fa.allocator(), k, &list)) |ok| {
            var info = ok;
            info.deinit(fa.allocator());
        } else |err| try testing.expectEqual(error.OutOfMemory, err);
    }
}

const build_seeds = [_][]const u8{
    "",
    "\x02\x01\x00\x03abc\x01\x00\x03def",
    "\x03\x01\x00\x01a\x02\x00\x01b\x02\x00\x01c",
    "\x02\x00\x00\x00\x00\x00\x00",
    "\x01\xfa\x50\x02xy",
    "\x08\x01\x01\x01\x02\x02\x02\x03\x03\x03\x04\x04\x04\x04\x04\x04\x04",
};

test "fuzz: buildFromLeaves never panics; success implies a complete tree with matching paths" {
    try testing.fuzz({}, fuzzBuild, .{ .corpus = &build_seeds });
}

fn fuzzBuild(_: void, smith: *std.testing.Smith) !void {
    var scripts: [8][16]u8 = undefined;
    var list: [8]tree.DepthLeaf = undefined;
    // Full-width draws reduced by hand: a `u8` draw reads eight input bytes
    // and answers its minimum unless they already fit, which collapsed every
    // seed into one input (`check-fuzz-reach` R1; testkit/src/fuzz.zig).
    const n: usize = @intCast(smith.value(u64) % 9);
    for (0..n) |i| {
        const raw: u8 = @truncate(smith.value(u64));
        const depth: u8 = if (raw >= 250) raw - 120 else raw % 5; // 0..4, or 130..135 (too deep)
        const len = smith.slice(&scripts[i]);
        list[i] = .{ .depth = depth, .version = @truncate(smith.value(u64)), .script = scripts[i][0..len] };
    }
    const k = try internalKey();
    var info = tree.buildFromLeaves(ta, k, list[0..n]) catch return;
    defer info.deinit(ta);
    try testing.expectEqual(n, info.leaves.len);
    if (n == 0) return try testing.expect(info.merkle_root == null);
    var kraft: u32 = 0; // sum of 2^(4-depth) must be exactly 2^4: a complete tree
    for (info.leaves, list[0..n]) |leaf, l| {
        try testing.expect(l.depth <= 4);
        try testing.expectEqual(@as(usize, l.depth), leaf.path.len);
        try testing.expect(tree.validLeafVersion(l.version));
        kraft += @as(u32, 1) << @intCast(4 - l.depth);
    }
    try testing.expectEqual(@as(u32, 16), kraft);
}

// ── control-block parsing and commitment verification ───────────────────

test "ControlBlock.parse: size rules and fields" {
    var buf: [33 + 32 * 129]u8 = @splat(0x07);
    buf[0] = 0xc1;
    const cb = try tree.ControlBlock.parse(buf[0..33]);
    try testing.expectEqual(@as(u8, 0xc0), cb.leaf_version);
    try testing.expectEqual(@as(u1, 1), cb.output_parity);
    try testing.expectEqual(@as(usize, 0), cb.pathLen());
    try testing.expectEqual(@as(usize, 128), (try tree.ControlBlock.parse(buf[0 .. 33 + 32 * 128])).pathLen());
    try testing.expectEqual(@as(usize, 1), (try tree.ControlBlock.parse(buf[0..65])).pathLen());
    for ([_]usize{ 0, 1, 32, 34, 64, 66, 33 + 32 * 128 + 32, 33 + 32 * 128 + 1 }) |n| {
        try testing.expectError(error.InvalidControlBlockSize, tree.ControlBlock.parse(buf[0..n]));
    }
}

/// Every leaf of `info` verifies, and any single flipped byte of the control
/// block, the output key or the script is refused.
fn checkVerify(info: tree.SpendInfo) !void {
    for (info.leaves, 0..) |leaf, i| {
        const cb = try info.controlBlockAlloc(ta, i);
        defer ta.free(cb);
        try testing.expect(taproot.verifyCommitment(info.output.x, cb, leaf.script));
        const parsed = try tree.ControlBlock.parse(cb);
        if (info.merkle_root) |r| try testing.expectEqualSlices(u8, &r, &parsed.merkleRoot(leaf.leaf_hash));
        for (0..cb.len) |k| {
            cb[k] ^= 0x01;
            try testing.expect(!taproot.verifyCommitment(info.output.x, cb, leaf.script));
            cb[k] ^= 0x01;
        }
        var q = info.output.x;
        q[31] ^= 0x01;
        try testing.expect(!taproot.verifyCommitment(q, cb, leaf.script));
        try testing.expect(!taproot.verifyCommitment(info.output.x, cb, "\x00 other script"));
        try testing.expect(!taproot.verifyCommitment(info.output.x, cb[0 .. cb.len - 1], leaf.script));
    }
}

test "verifyCommitment: every control block of every BIP341 vector tree" {
    for (v.rows) |row| {
        const internal = try bip340.XOnlyPublicKey.fromBytes(try hex32(row.internal_pubkey));
        var info = try taproot.buildFromLeaves(ta, internal, row.leaves);
        defer info.deinit(ta);
        try checkVerify(info);
        // the published control blocks (BIP341 JSON) verify too
        for (info.leaves, row.control_blocks) |leaf, cb_hex| {
            const cb = try hexAlloc(cb_hex);
            defer ta.free(cb);
            try testing.expect(taproot.verifyCommitment(try hex32(row.tweaked_pubkey), cb, leaf.script));
        }
    }
}

test "verifyCommitment: an off-curve internal key and an out-of-range tweak are refused, not trapped" {
    // BIP340 vector 5's x is not on the curve.
    var cb: [33]u8 = undefined;
    cb[0] = 0xc0;
    _ = try std.fmt.hexToBytes(cb[1..], "EEFDEA4CDB677750A420FEE807EACF21EB9898AE79B9768766E4FAA04A2D4A34");
    try testing.expect(!taproot.verifyCommitment(@splat(0x11), &cb, "x"));
}
